Here's a C++ Qt5 application that converts Excel files to CSV:

```cpp
// main.cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QLabel>
#include <QMessageBox>
#include <QDir>
#include <QProgressBar>
#include <QAxObject>
#include <QDebug>

class ExcelToCsvConverter : public QWidget {
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr) : QWidget(parent) {
        setWindowTitle("Excel to CSV Converter");
        setMinimumSize(450, 200);

        // Setup UI
        QVBoxLayout *layout = new QVBoxLayout(this);

        titleLabel = new QLabel("Excel to CSV Converter", this);
        titleLabel->setAlignment(Qt::AlignCenter);
        titleLabel->setStyleSheet("font-size: 18px; font-weight: bold; margin: 10px;");
        layout->addWidget(titleLabel);

        selectedDirLabel = new QLabel("No directory selected", this);
        selectedDirLabel->setAlignment(Qt::AlignCenter);
        selectedDirLabel->setStyleSheet("color: gray; margin: 5px;");
        selectedDirLabel->setWordWrap(true);
        layout->addWidget(selectedDirLabel);

        selectDirButton = new QPushButton("Select Directory", this);
        selectDirButton->setStyleSheet("padding: 8px; font-size: 14px;");
        layout->addWidget(selectDirButton);

        convertButton = new QPushButton("Convert to CSV", this);
        convertButton->setStyleSheet("padding: 8px; font-size: 14px;");
        convertButton->setEnabled(false);
        layout->addWidget(convertButton);

        progressBar = new QProgressBar(this);
        progressBar->setVisible(false);
        layout->addWidget(progressBar);

        statusLabel = new QLabel("", this);
        statusLabel->setAlignment(Qt::AlignCenter);
        statusLabel->setWordWrap(true);
        layout->addWidget(statusLabel);

        // Connect signals
        connect(selectDirButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
        connect(convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);
    }

private slots:
    void selectDirectory() {
        QString dir = QFileDialog::getExistingDirectory(
            this,
            "Select Directory Containing Excel Files",
            QDir::homePath(),
            QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
        );

        if (!dir.isEmpty()) {
            selectedDirectory = dir;
            selectedDirLabel->setText("Selected: " + dir);
            selectedDirLabel->setStyleSheet("color: black; margin: 5px;");
            convertButton->setEnabled(true);

            // Count Excel files
            QDir directory(dir);
            QStringList filters;
            filters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";
            QFileInfoList files = directory.entryInfoList(filters, QDir::Files);
            statusLabel->setText(QString("Found %1 Excel file(s)").arg(files.size()));
        }
    }

    void convertFiles() {
        if (selectedDirectory.isEmpty()) {
            QMessageBox::warning(this, "Warning", "Please select a directory first.");
            return;
        }

        QDir dir(selectedDirectory);

        // Find all Excel files
        QStringList filters;
        filters << "*.xlsx" << "*.xls" << "*.xlsm" << "*.xlsb";
        QFileInfoList excelFiles = dir.entryInfoList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "Info", "No Excel files found in the selected directory.");
            return;
        }

        // Create output directory
        QString outputDirName = "csv_output";
        QString outputPath = selectedDirectory + QDir::separator() + outputDirName;
        if (!dir.exists(outputDirName)) {
            if (!dir.mkdir(outputDirName)) {
                QMessageBox::critical(this, "Error", "Failed to create output directory.");
                return;
            }
        }

        // Setup progress bar
        progressBar->setVisible(true);
        progressBar->setMinimum(0);
        progressBar->setMaximum(excelFiles.size());
        progressBar->setValue(0);

        // Disable buttons during conversion
        selectDirButton->setEnabled(false);
        convertButton->setEnabled(false);

        // Initialize Excel COM object
        QAxObject *excel = new QAxObject("Excel.Application", this);
        if (excel->isNull()) {
            QMessageBox::critical(this, "Error",
                "Failed to initialize Microsoft Excel.\n"
                "Make sure Microsoft Excel is installed on your system.");
            selectDirButton->setEnabled(true);
            convertButton->setEnabled(true);
            progressBar->setVisible(false);
            delete excel;
            return;
        }

        excel->setProperty("Visible", false);
        excel->setProperty("DisplayAlerts", false);

        QAxObject *workbooks = excel->querySubObject("Workbooks");

        int successCount = 0;
        int failCount = 0;
        QStringList failedFiles;

        for (int i = 0; i < excelFiles.size(); ++i) {
            const QFileInfo &fileInfo = excelFiles[i];
            QString inputFilePath = QDir::toNativeSeparators(fileInfo.absoluteFilePath());
            QString baseName = fileInfo.completeBaseName();

            statusLabel->setText(QString("Converting: %1").arg(fileInfo.fileName()));
            QApplication::processEvents();

            try {
                // Open the workbook
                QAxObject *workbook = workbooks->querySubObject(
                    "Open(const QString&, QVariant, QVariant)",
                    inputFilePath, 0, true  // 0 = don't update links, true = read-only
                );

                if (workbook && !workbook->isNull()) {
                    // Get all sheets
                    QAxObject *sheets = workbook->querySubObject("Worksheets");
                    int sheetCount = sheets->property("Count").toInt();

                    if (sheetCount == 1) {
                        // Single sheet - save as one CSV
                        QString csvFilePath = QDir::toNativeSeparators(
                            outputPath + QDir::separator() + baseName + ".csv"
                        );

                        // xlCSV = 6
                        workbook->dynamicCall(
                            "SaveAs(const QString&, int)",
                            csvFilePath, 6
                        );
                    } else {
                        // Multiple sheets - save each sheet as separate CSV
                        for (int s = 1; s <= sheetCount; ++s) {
                            QAxObject *sheet = sheets->querySubObject("Item(int)", s);
                            QString sheetName = sheet->property("Name").toString();

                            // Clean sheet name for file system
                            sheetName.replace(QRegExp("[\\\\/:*?\"<>|]"), "_");

                            QString csvFilePath = QDir::toNativeSeparators(
                                outputPath + QDir::separator() + baseName + "_" + sheetName + ".csv"
                            );

                            // Activate the sheet
                            sheet->dynamicCall("Activate()");

                            // Copy the sheet to a new workbook and save as CSV
                            sheet->dynamicCall("Copy()");

                            // The copied sheet is now in a new active workbook
                            QAxObject *activeWorkbook = excel->querySubObject("ActiveWorkbook");
                            if (activeWorkbook && !activeWorkbook->isNull()) {
                                activeWorkbook->dynamicCall(
                                    "SaveAs(const QString&, int)",
                                    csvFilePath, 6
                                );
                                activeWorkbook->dynamicCall("Close(bool)", false);
                                delete activeWorkbook;
                            }

                            delete sheet;
                        }
                    }

                    delete sheets;
                    workbook->dynamicCall("Close(bool)", false);
                    delete workbook;
                    successCount++;
                } else {
                    failCount++;
                    failedFiles.append(fileInfo.fileName());
                }
            } catch (...) {
                failCount++;
                failedFiles.append(fileInfo.fileName());
            }

            progressBar->setValue(i + 1);
            QApplication::processEvents();
        }

        // Clean up Excel
        delete workbooks;
        excel->dynamicCall("Quit()");
        delete excel;

        // Re-enable buttons
        selectDirButton->setEnabled(true);
        convertButton->setEnabled(true);

        // Show results
        QString resultMsg = QString("Conversion complete!\n\n"
                                    "Successfully converted: %1 file(s)\n"
                                    "Failed: %2 file(s)\n\n"
                                    "Output directory: %3")
                                .arg(successCount)
                                .arg(failCount)
                                .arg(outputPath);

        if (!failedFiles.isEmpty()) {
            resultMsg += "\n\nFailed files:\n" + failedFiles.join("\n");
        }

        statusLabel->setText(QString("Done! %1 converted, %2 failed").arg(successCount).arg(failCount));

        QMessageBox::information(this, "Conversion Complete", resultMsg);
    }

private:
    QString selectedDirectory;
    QLabel *titleLabel;
    QLabel *selectedDirLabel;
    QLabel *statusLabel;
    QPushButton *selectDirButton;
    QPushButton *convertButton;
    QProgressBar *progressBar;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    ExcelToCsvConverter converter;
    converter.show();

    return app.exec();
}

#include "main.moc"
```

And here's the project file:

```pro
# ExcelToCsvConverter.pro
QT       += core gui widgets axcontainer

TARGET = ExcelToCsvConverter
TEMPLATE = app

CONFIG += c++11

SOURCES += main.cpp
```

## How to Build and Run

1. Save `main.cpp` and `ExcelToCsvConverter.pro` in the same directory.
2. Open a Qt command prompt and run:
   ```bash
   qmake ExcelToCsvConverter.pro
   nmake        # (or mingw32-make if using MinGW)
   ```
3. Run the generated executable.

## How It Works

1. **Directory Selection** – The user clicks "Select Directory" and a native folder picker dialog opens. The app scans for `.xlsx`, `.xls`, `.xlsm`, and `.xlsb` files.

2. **Conversion** – When "Convert to CSV" is clicked:
   - A `csv_output` subfolder is created in the selected directory
   - The app launches Excel via **COM Automation** (`QAxObject` wrapping `Excel.Application`)
   - Each Excel file is opened in read-only mode
   - **Single-sheet** workbooks are saved directly as CSV
   - **Multi-sheet** workbooks produce one CSV per sheet (named `filename_sheetname.csv`)
   - A progress bar tracks the conversion

3. **Cleanup** – Excel is closed programmatically, and a summary dialog reports successes and failures.

## Important Notes

- **Requires Microsoft Excel installed** – This uses Excel's COM automation interface (`QAxObject`), which is Windows-only and requires a local Excel installation.
- **Windows only** – `QAxContainer` is a Windows-specific Qt module.
- If you need a cross-platform solution (no Excel dependency), you'd need a library like [**QXlsx**](https://github.com/QtExcel/QXlsx) or [**libxlsxwriter**](https://libxlsxwriter.github.io/) to read Excel files and write CSV manually. Let me know if you'd like that alternative!

